import{_ as a,o as e,c as s,ag as i}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"PlaceholderAPI 变量","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/placeholders.md","filePath":"shitbot/placeholders.md"}'),d={name:"shitbot/placeholders.md"};function l(o,t,h,p,n,r){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="placeholderapi-变量" tabindex="-1">PlaceholderAPI 变量 <a class="header-anchor" href="#placeholderapi-变量" aria-label="Permalink to &quot;PlaceholderAPI 变量&quot;">​</a></h1><p>ShitBot 有两个 PAPI 使用方向：向计分板、菜单等插件提供自己的状态变量，以及在高级图片模板中读取其他插件提供的变量。</p><h2 id="在计分板或菜单显示-shitbot-状态" tabindex="-1">在计分板或菜单显示 ShitBot 状态 <a class="header-anchor" href="#在计分板或菜单显示-shitbot-状态" aria-label="Permalink to &quot;在计分板或菜单显示 ShitBot 状态&quot;">​</a></h2><p>在 Spigot/Paper/Folia 服务端安装兼容该服务端与 Java 版本的 PlaceholderAPI，再正常启动 ShitBotSpigot。ShitBot 会自动注册内置扩展，无需额外下载 <code>shitbot</code> expansion，也无需开启高级渲染组件。</p><table tabindex="0"><thead><tr><th>变量</th><th>内容</th></tr></thead><tbody><tr><td><code>%shitbot_version%</code></td><td>ShitBot 插件版本</td></tr><tr><td><code>%shitbot_ready%</code></td><td>运行实例与数据库是否已就绪，<code>true</code> / <code>false</code></td></tr><tr><td><code>%shitbot_connected%</code></td><td>当前实例的 OneBot 是否已连接，<code>true</code> / <code>false</code>；backend 通常为 false</td></tr><tr><td><code>%shitbot_whitelisted%</code></td><td>当前玩家是否有 ShitBot 白名单条目，包括无 QQ 白名单</td></tr><tr><td><code>%shitbot_bound%</code></td><td>当前玩家是否有 QQ 归属；无 QQ 白名单为 <code>false</code></td></tr><tr><td><code>%shitbot_qq%</code></td><td>当前玩家绑定的 QQ；无 QQ 白名单或未绑定时为空</td></tr></tbody></table><p>玩家变量按精确游戏 ID 查询，区分大小写。PAPI 同步回调不会等待数据库：第一次读取会提交异步查询并返回空字符串，后续读取使用最长 5 秒的缓存；无玩家上下文、实例未就绪或查询失败也返回空字符串。缓存最多保存 512 个玩家，reload 后自动切换到新运行实例。它们适合展示信息，登录和命令授权仍由数据库业务接口决定。</p><p><code>%shitbot_qq%</code> 会显示真实 QQ，请只放在你希望展示此信息的位置。它不会把无 QQ 白名单伪装成某个 QQ 的角色。</p><h2 id="在图片里使用其他插件变量" tabindex="-1">在图片里使用其他插件变量 <a class="header-anchor" href="#在图片里使用其他插件变量" aria-label="Permalink to &quot;在图片里使用其他插件变量&quot;">​</a></h2><p>高级模板的 <code>manifest.yml</code> 显式声明 <code>papi</code> 数据提供器：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">papi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    player</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${context.player}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${context.server}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    placeholders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%player_displayname%&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      balance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%vault_eco_balance_formatted%&quot;</span></span></code></pre></div><p>在 <code>scene.yml</code> 的文本节点写 <code>\${data.papi.display_name}</code> 或 <code>\${data.papi.balance}</code>。还需安装提供这些变量的插件及对应扩展。未解析的变量、缺少插件、离线玩家及超时会产生明确错误。</p><p>BungeeCord/Velocity 通过认证后端通道请求目标 Spigot 子服解析，代理不加载 Bukkit 的 PlaceholderAPI；<code>server</code> 使用代理中配置的子服名。Nukkit-MOT 不支持 Bukkit PAPI，可以用 ShitBot 内置数据提供器或第三方自定义提供器。</p><p>完整的查询限制、缓存、线程调度、错误显示和命令示例见<a href="./image-templates.html#placeholderapi-与代理后端">图片渲染与高级模板</a>。扩展接入方式遵循 <a href="https://wiki.placeholderapi.com/developers/creating-a-placeholderexpansion/" target="_blank" rel="noreferrer">PlaceholderAPI 的内置扩展接口</a>。</p>`,13)])])}const E=a(d,[["render",l]]);export{k as __pageData,E as default};
